 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones — and purged issues
 * leave their number behind in the project's watermark, so it is never reused.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return highestIssueNumber(getDb(), orgId, projectId) + 1;
}

type DbLike = Pick<ReturnType<typeof getDb>, "select">;

/** The highest number the project has ever used, purged issues included. */
function highestIssueNumber(
  db: DbLike,
  orgId: OrgId,
  projectId: ProjectId,
): number {
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();

  const watermark = db
    .select({ value: issueNumberWatermarks.lastNumber })
    .from(issueNumberWatermarks)
    .where(
      and(
        orgPredicate(issueNumberWatermarks.orgId, orgId),
        eq(issueNumberWatermarks.projectId, projectId),
      ),
    )
    .get();

  return Math.max(row?.value ?? 0, watermark?.value ?? 0);
}''')
s=s.replace('''/** Cascade behind `ProjectService.archiveProject`; returns the row count. */''','''/**
 * Every archived issue of the org whose `archived_at` is at or before
 * `cutoff`, across all projects and without paging — the retention sweep
 * must see all of them.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(issues.archivedAt, issues.id)
    .all();

  return rows.map((row) => toIssue(row));
}

export type PurgedIssue = {
  readonly issueId: IssueId;
  readonly commentIds: readonly string[];
  readonly attachmentSizes: readonly number[];
};

/**
 * Hard-deletes one issue with its label links, comments and attachments, in
 * one transaction. The project's number watermark is raised first so the
 * purged number is never handed out again. Returns what was removed so the
 * caller can drop search documents and give storage back.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue | null> {
  return getDb().transaction((tx) => {
    const issue = tx
      .select({ id: issues.id, projectId: issues.projectId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!issue) return null;

    const projectId = issue.projectId as ProjectId;
    const lastNumber = highestIssueNumber(tx, orgId, projectId);
    tx.insert(issueNumberWatermarks)
      .values({ orgId, projectId, lastNumber })
      .onConflictDoUpdate({
        target: issueNumberWatermarks.projectId,
        set: { lastNumber },
      })
      .run();

    const commentRows = tx
      .delete(comments)
      .where(
        and(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
        ),
      )
      .returning({ id: comments.id })
      .all();

    const attachmentRows = tx
      .delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .returning({ sizeBytes: attachments.sizeBytes })
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();

    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .run();

    return {
      issueId,
      commentIds: commentRows.map((row) => row.id),
      attachmentSizes: attachmentRows.map((row) => row.sizeBytes),
    };
  });
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */''')
