import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { RestoreRefusedError } from "@/lib/soft-delete";
import { toAppError } from "@/lib/errors";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("trash", () => {
  it("restores and purges", async () => {
    const t = await createTenant("trash");
    const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "A zebra" }));
    const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "B" }));
    await usageRepo.recomputeUsage(t.org.id);
    await expect(issueService.restoreIssue(t.actors.member, t.org.id, b.id)).rejects.toMatchObject({ reason: "not_archived" });
    await issueService.archiveIssue(t.actors.member, t.org.id, b.id);
    const u1 = await usageRepo.getUsage(t.org.id);
    const r = await issueService.restoreIssue(t.actors.member, t.org.id, b.id);
    expect(r.archivedAt).toBeNull(); expect(r.number).toBe(2);
    expect((await usageRepo.getUsage(t.org.id)).issuesUsed).toBe(u1.issuesUsed + 1);
    const acts = await activityRepo.listActivity({ orgId: t.org.id, action: ["issue.restored"], limit: 10, cursor: null });
    expect(acts.items).toHaveLength(1);
    expect(toAppError(new RestoreRefusedError("Issue", "x", "quota")).code).toBe("conflict");

    const c = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: b.id, body: "zebra comment" } as never);
    await attachmentService.addAttachment(t.actors.member, { orgId: t.org.id, issueId: b.id, filename: "f", contentType: "text/plain", sizeBytes: 1500000 } as never);
    await attachmentService.addAttachment(t.actors.member, { orgId: t.org.id, issueId: a.id, filename: "g", contentType: "text/plain", sizeBytes: 100 } as never);
    await issueService.archiveIssue(t.actors.member, t.org.id, b.id);
    expect((await usageRepo.getUsage(t.org.id)).storageMbUsed).toBe(3);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date(Date.now() + 366 * 86400000));
    await expect(issueService.restoreIssue(t.actors.member, t.org.id, b.id)).rejects.toMatchObject({ reason: "expired" });
    const res = await runCleanupArchivedJob(new Date());
    console.log(res);
    vi.useRealTimers();
    expect(await issueRepo.findIssueById(t.org.id, b.id)).toBeNull();
    expect(await searchRepo.countIndexed(t.org.id)).toBeGreaterThan(0);
    const hits = await searchRepo.searchDocuments({ orgId: t.org.id, q: "zebra", kinds: [], limit: 10, cursor: null } as never);
    expect(hits.items.map((h) => h.subjectId)).toEqual([a.id]);
    const u = await usageRepo.getUsage(t.org.id);
    const full = await usageRepo.recomputeUsage(t.org.id);
    expect(u.storageMbUsed).toBe(full.storageMbUsed);
    expect(await issueRepo.nextIssueNumber(t.org.id, t.project.id)).toBe(3);
    await expect(issueService.restoreIssue(t.actors.member, t.org.id, b.id)).rejects.toBeInstanceOf(NotFoundError);
    void c;
  });
});
